只复用一个 seed 还不够：如果攻击才抽随机数、喝药不抽，不同策略会让后面的随机序列错位。下面先为每回合生成攻击和反击结果，再把相同 tape 交给两个配置；即使某项未使用，也不把后面的结果前移。策略只能看到当前状态，不能看到 tape。

```js
// 保存为 battle-probe.mjs，运行 node battle-probe.mjs。
function makeTape(seed, turns = 12) {
  let x = seed >>> 0;
  const rand = () => {
    x = (x + 0x6D2B79F5) >>> 0;
    let t = Math.imul(x ^ (x >>> 15), x | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  return Array.from({ length: turns }, () => ({
    hit: 14 + Math.floor(rand() * 5),
    hurt: (9 + Math.floor(rand() * 7)) * (rand() < 0.15 ? 2 : 1)
  }));
}
function fight(tape, heal, policy) {
  let hp = 60, foe = 80, potions = 1;
  const trace = [];
  for (const [i, roll] of tape.entries()) {
    const action = policy({ hp, foe, potions });
    if (action === "heal" && potions > 0) {
      hp = Math.min(60, hp + heal); potions--;
    } else if (action === "attack") {
      foe = Math.max(0, foe - roll.hit);
    } else throw new Error("非法动作或药水耗尽");
    if (foe > 0) hp = Math.max(0, hp - roll.hurt);
    trace.push({ turn: i + 1, action, hp, foe, potions });
    if (foe === 0 || hp === 0) {
      return { result: foe === 0 ? "win" : "loss", trace };
    }
  }
  return { result: "timeout", trace };
}
const policies = {
  rush: () => "attack",
  cautious: s => s.hp <= 30 && s.potions > 0 ? "heal" : "attack"
};
const seeds = Array.from({ length: 400 }, (_, i) => i + 1001);
for (const [name, policy] of Object.entries(policies)) {
  const rows = seeds.map(seed => {
    const tape = makeTape(seed);
    return { seed, a: fight(tape, 24, policy), b: fight(tape, 30, policy) };
  });
  console.log({ policy: name, n: rows.length,
    aWins: rows.filter(r => r.a.result === "win").length,
    bWins: rows.filter(r => r.b.result === "win").length,
    improved: rows.filter(r => r.a.result !== "win" && r.b.result === "win").length,
    regressed: rows.filter(r => r.a.result === "win" && r.b.result !== "win").length,
    aTimeouts: rows.filter(r => r.a.result === "timeout").length,
    bTimeouts: rows.filter(r => r.b.result === "timeout").length
  });
  const changed = rows.find(r => r.a.result !== r.b.result);
  if (changed) console.log("first difference", JSON.stringify(changed));
}
```

这里的伪随机发生器只用于可复现教学模拟，不用于安全抽奖。1001–1400 是固定的演示种子集合；400 是练习规模，不是足够统计可信度的保证。每个策略分别跑 400 组 A/B，共 1600 场，A 回 24 血，B 回 30 血；函数每次重置生命和药水，且不修改 tape。

接入自己的项目时，应从真实战斗模块抽出结算函数，共享同一套规则。正文为了可以独立复制，才内置一份小裁判；如果生产逻辑另写一份，必须对齐回合轨迹，防止测试通过的是另一个游戏。
